#include "h3/audio.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>

using namespace h3;
#define CHECK(x) do{if(!(x))throw std::runtime_error(std::string("line ")+std::to_string(__LINE__)+": "+#x);}while(false)
struct Files {std::filesystem::path root;Files(){auto stamp=std::chrono::high_resolution_clock::now().time_since_epoch().count();for(int i=0;i<1000;i++){auto path=std::filesystem::temp_directory_path()/("h3-audio-"+std::to_string(stamp)+"-"+std::to_string(i));if(std::filesystem::create_directory(path)){root=std::move(path);return;}}throw std::runtime_error("No audio test directory");}~Files(){std::error_code error;std::filesystem::remove_all(root,error);}};
float peak(const AudioClip&clip){float result=0;for(float sample:clip->samples){CHECK(std::isfinite(sample));result=std::max(result,std::abs(sample));}return result;}
void writeWav(const std::filesystem::path&path,const std::vector<float>&samples){
 if(!path.parent_path().empty())std::filesystem::create_directories(path.parent_path());std::ofstream file(path,std::ios::binary);
 auto number=[&](uint32_t n,int bytes){for(int i=0;i<bytes;i++)file.put(char(n>>(8*i)));};
 file.write("RIFF",4);number(uint32_t(samples.size()*2+36),4);file.write("WAVEfmt ",8);number(16,4);number(1,2);number(2,2);number(AudioRate,4);number(AudioRate*4,4);number(4,2);number(16,2);file.write("data",4);number(uint32_t(samples.size()*2),4);
 for(float sample:samples)number(uint16_t(int16_t(std::round(std::clamp(sample,-1.f,1.f)*32767))),2);CHECK(file.good());
}
int main(int argc,char**argv){
 SDL_setenv("SDL_AUDIODRIVER","dummy",1);if(SDL_Init(SDL_INIT_AUDIO|SDL_INIT_TIMER)!=0){std::cerr<<SDL_GetError()<<'\n';return 1;}
 int passed=0,failed=0;auto run=[&](const char*name,auto test){try{test();passed++;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception&e){failed++;std::cerr<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
 const std::filesystem::path root=H3_TEST_SOURCE_ROOT;Files files;std::ifstream input(root/"assets/audio/manifest.json");auto catalog=nlohmann::json::parse(input);AudioEngine engine(root,false);
 run("client settings persist audio and supported original options",[&]{ClientSettings a;a.music=2;a.effects=8;a.muted=true;a.heroSpeed=0;a.scrollSpeed=2;a.showPath=false;a.townOutlines=false;a.battleGrid=false;a.hdArtwork=false;std::string error;auto path=files.root/"options.json";CHECK(a.save(path,error));ClientSettings b;CHECK(b.load(path,error)&&a==b);CHECK(!std::filesystem::exists(path.string()+".tmp"));});
 run("legacy client options enable HD and malformed quality flags preserve settings",[&]{auto path=files.root/"legacy-options.json";auto json=nlohmann::json{{"version",1},{"music",5},{"effects",5},{"muted",false}};std::ofstream(path)<<json.dump();ClientSettings value;value.hdArtwork=false;std::string error;CHECK(value.load(path,error)&&value.hdArtwork);auto before=value;json["hdArtwork"]=2;std::ofstream(path)<<json.dump();CHECK(!value.load(path,error)&&value==before);});
 run("invalid client settings never overwrite accepted values",[&]{ClientSettings value;value.music=3;auto before=value;auto path=files.root/"invalid.json";std::string error;
  for(auto json:{nlohmann::json{{"version",1},{"music",-1},{"effects",5},{"muted",false}},nlohmann::json{{"version",1},{"music",uint64_t(4294967299)},{"effects",5},{"muted",false}},nlohmann::json{{"version",1},{"music",5},{"effects",5},{"muted",false},{"heroSpeed",1.5}},nlohmann::json{{"version",1},{"music",5},{"effects",5},{"muted",false},{"showPath",2}}}){std::ofstream(path)<<json.dump();CHECK(!value.load(path,error)&&value==before);}
  std::ofstream(path)<<std::string(5000,'x');CHECK(!value.load(path,error)&&value==before);
 });
 run("all combined original demo IMA ADPCM sounds decode to stereo PCM",[&]{CHECK(catalog["sounds"].size()==951);for(auto it=catalog["sounds"].begin();it!=catalog["sounds"].end();++it){auto clip=engine.load("sounds",it.key());CHECK(clip&&clip->frames()>0);CHECK(peak(clip)>0);}CHECK(engine.cacheSize()<=96);});
 run("all twenty-seven music tracks decode with preserved duration",[&]{CHECK(catalog["music"].size()==27);for(auto it=catalog["music"].begin();it!=catalog["music"].end();++it){auto clip=engine.load("music",it.key());CHECK(clip&&peak(clip)>0);double expected=it.value()["seconds"].get<double>()*AudioRate;if(std::abs(double(clip->frames())-expected)>=64)throw std::runtime_error(it.key()+": expected "+std::to_string(expected)+" frames, decoded "+std::to_string(clip->frames()));}CHECK(engine.cacheSize()<=98);});
 run("all nine faction themes and four battle tracks are available",[&]{for(const auto&faction:Factions)CHECK(catalog["music"].contains("town."+faction.key));for(int i=1;i<=4;i++)CHECK(catalog["music"].contains("combat."+std::to_string(i)));for(auto terrain:{"grass","dirt","sand","water"})CHECK(catalog["music"].contains(std::string("terrain.")+terrain));CHECK(catalog["music"].contains("menu.main"));});
 run("mono original button effects preserve channel equality",[&]{auto clip=engine.load("sounds","button.wav");CHECK(clip&&peak(clip)>0);for(size_t i=0;i<clip->frames();i++)CHECK(std::abs(clip->samples[i*2]-clip->samples[i*2+1])<.000001f);});
 run("structured combat and spell events select the original resource names",[&]{engine.clear();std::array events{GameEvent{GameEventType::CombatAttack,Pikeman},GameEvent{GameEventType::CombatAttack,Archer,1},GameEvent{GameEventType::CombatHit,Pikeman},GameEvent{GameEventType::CombatDeath,Pikeman},GameEvent{GameEventType::SpellCast,-1,MagicArrow}};engine.consume(events);auto played=engine.takePlayed();CHECK((played==std::vector<std::string>{"pikeattk.wav","lcrsshot.wav","pikewnce.wav","pikekill.wav","magicblt.wav"}));});
 run("lucky attacks use the verified original lucky strike cue",[&]{engine.clear();auto game=Game::create();auto state=game.toJson();std::array events{GameEvent{GameEventType::CombatLuck,Pikeman,1}};events[0].scheduled=true;engine.consume(events);CHECK(engine.takePlayed()==std::vector<std::string>{"goodluck.wav"});CHECK(game.toJson()==state);});
 run("positive and negative morale use their distinct original proc sounds",[&]{engine.clear();std::array events{GameEvent{GameEventType::CombatMorale,Pikeman,1},GameEvent{GameEventType::CombatMorale,Pikeman,-1}};for(auto&e:events)e.scheduled=true;engine.consume(events);CHECK((engine.takePlayed()==std::vector<std::string>{"goodmrle.wav","badmrle.wav"}));});
 run("mass spell effects do not duplicate the single spell cast sound",[&]{engine.clear();std::array events{GameEvent{GameEventType::SpellCast,-1,Mirth},GameEvent{GameEventType::CombatSpellEffect,Pikeman,Mirth},GameEvent{GameEventType::CombatSpellEffect,30,Mirth}};for(auto&e:events)e.scheduled=true;engine.consume(events);CHECK(engine.takePlayed()==std::vector<std::string>{"mirth.wav"});});
 run("scheduled morale sound starts immediately with its visual rather than legacy delay",[&]{std::vector<float> scheduled(12000),direct(12000);std::array events{GameEvent{GameEventType::CombatAttack,Pikeman},GameEvent{GameEventType::CombatMorale,Pikeman,1}};for(auto&e:events)e.scheduled=true;engine.clear();engine.consume(events);engine.offline(scheduled);engine.clear();engine.effect("pikeattk.wav");engine.effect("goodmrle.wav");engine.offline(direct);CHECK(scheduled==direct);});
 run("timeline scheduled cues do not receive a second audio delay",[&]{
  std::array events{GameEvent{GameEventType::CombatAttack,Pikeman},GameEvent{GameEventType::CombatHit,Pikeman}};for(auto&e:events)e.scheduled=true;std::vector<float> scheduled(12000),direct(12000),legacy(12000);engine.clear();engine.consume(events);engine.offline(scheduled);engine.clear();engine.effect("pikeattk.wav");engine.effect("pikewnce.wav");engine.offline(direct);CHECK(scheduled==direct);engine.clear();for(auto&e:events)e.scheduled=false;engine.consume(events);engine.offline(legacy);CHECK(legacy!=scheduled);
 });
 run("adventure landmarks play their original visit sounds",[&]{engine.clear();std::array events{GameEvent{GameEventType::Visit,28,int(ObjectType::Site)},GameEvent{GameEventType::Visit,31,int(ObjectType::Site)},GameEvent{GameEventType::Visit,94,int(ObjectType::Site)},GameEvent{GameEventType::Visit,96,int(ObjectType::Site)},GameEvent{GameEventType::Visit,48,int(ObjectType::Site)},GameEvent{GameEventType::Visit,55,int(ObjectType::Site)}};engine.consume(events);CHECK((engine.takePlayed()==std::vector<std::string>{"luck.wav","morale.wav","store.wav","temple.wav","faerie.wav","expernce.wav"}));});
 run("day week and month cues follow the game day without changing RNG",[&]{engine.clear();auto g=Game::create();auto before=g.toJson();std::array events{GameEvent{GameEventType::NewDay,-1,2},GameEvent{GameEventType::NewDay,-1,8},GameEvent{GameEventType::NewDay,-1,29}};engine.consume(events);CHECK((engine.takePlayed()==std::vector<std::string>{"newday.wav","newweek.wav","newmonth.wav"}));CHECK(g.toJson()==before);});
 run("missing expansion unit cues are silent instead of substituted",[&]{engine.clear();CHECK(!engine.effect("missing-original.wav"));std::array events{GameEvent{GameEventType::CombatAttack,117}};engine.consume(events);CHECK(engine.takePlayed().empty());});
 run("Windows supplement supplies previously silent original elf attacks",[&]{engine.clear();std::array events{GameEvent{GameEventType::CombatAttack,19},GameEvent{GameEventType::CombatAttack,19,1},GameEvent{GameEventType::CombatDeath,19}};engine.consume(events);CHECK((engine.takePlayed()==std::vector<std::string>{"gelfattk.wav","gelfshot.wav","gelfkill.wav"}));CHECK(catalog["sounds"]["gelfattk.wav"]["edition"]=="windows-roe-demo");CHECK(catalog["sounds"]["pikeattk.wav"]["edition"]=="mac-complete-demo");});
 run("verified demo menu and scenario result themes override public rips",[&]{for(auto key:{"menu.main","report.scenario-win","report.ultimate-loss"}){CHECK(catalog["music"].contains(key));CHECK(catalog["music"][key]["source"]["record"]=="references/windows-demo/source.json");CHECK(engine.load("music",key));}});
 run("music is not restarted by repeated scene updates",[&]{engine.clear();engine.music("town.castle");std::vector<float> output(AudioRate*2);engine.offline(output);CHECK(std::any_of(output.begin(),output.end(),[](float value){return value!=0;}));CHECK(engine.theme()=="town.castle");engine.music("town.castle");engine.offline(output);CHECK(engine.theme()=="town.castle");});
 run("live SDL callback renders through an opened dummy output device",[&]{AudioEngine live(root,true);CHECK(live.available()&&live.outputActive());CHECK(live.effect("button.wav"));for(int i=0;i<30&&!live.outputFrames();i++)SDL_Delay(20);CHECK(live.outputFrames()>0);});
 run("removed ambient sources stop their looping output",[&]{engine.clear();std::array cues{AmbientCue{"looplumb.wav",3,.2f,-.2f}};engine.ambients(cues);std::vector<float> output(AudioRate*2);engine.offline(output);CHECK(std::any_of(output.begin(),output.end(),[](float value){return value!=0;}));engine.ambients({});engine.offline(output);CHECK(std::all_of(output.begin(),output.end(),[](float value){return value==0;}));});
 run("muting silences both music and effects without changing game state",[&]{engine.clear();auto game=Game::create();auto before=game.toJson();ClientSettings settings;settings.muted=true;engine.settings(settings);engine.music("town.castle");engine.effect("button.wav");std::vector<float> output(AudioRate*2);engine.offline(output);CHECK(std::all_of(output.begin(),output.end(),[](float value){return value==0;}));CHECK(game.toJson()==before);settings.muted=false;engine.settings(settings);});
 run("missing or invalid audio catalogs fail without stopping gameplay",[&]{AudioEngine missing(files.root,false);CHECK(!missing.available()&&!missing.effect("button.wav"));auto directory=files.root/"assets/audio";std::filesystem::create_directories(directory);std::ofstream(directory/"manifest.json")<<nlohmann::json{{"schema",1},{"sounds",{{"bad.wav",{{"file","../private.wav"}}}}}}.dump();AudioEngine bad(files.root,false);CHECK(!bad.load("sounds","bad.wav"));});
 if(argc==2){engine.clear();ClientSettings settings;engine.settings(settings);engine.music("town.castle");engine.effect("button.wav",1,0,AudioRate);engine.effect("magicblt.wav",1,0,AudioRate*3);std::vector<float> preview(AudioRate*8*2);engine.offline(preview);writeWav(argv[1],preview);}
 std::cout<<passed<<" audio checks passed, "<<failed<<" failed\n";SDL_Quit();return failed?1:0;
}
